const input = $input.item.json;
const p = input.projeto;
const remetente = input.remetente;

const staticData = $getWorkflowStaticData('global');
if (!staticData.contextos) staticData.contextos = {};
if (staticData.contextos[remetente]) {
  staticData.contextos[remetente].projeto_atual = p;
  staticData.contextos[remetente].projeto_exibido = false;
}

const percExec = parseFloat(String(p.PERCENTUAL_EXEC || "0").replace(",", "."));
let linhaExec = "📊 *Execução:* " + (p.PERCENTUAL_EXEC || "0") + "%";
if (!isNaN(percExec)) {
  if (percExec >= 80) linhaExec += " — execução avançada ✅";
  else if (percExec <= 10 && !(p.SITUACAO || "").toLowerCase().includes('conclu')) linhaExec += " — projeto em fase inicial";
}

return [{
  tipo: "projeto_selecionado",
  remetente,
  descricao_projeto:
    "Encontrei o projeto! Aqui estão os detalhes 📋\n\n" +
    "📄 *" + p.CODIGO_PROCESSO + " - " + p.NOME + "*\n\n" +
    "🟡 *Situação:* " + (p.SITUACAO || "-") + "\n" +
    "🏛 *Órgão:* " + (p.ORGAO || "-") + "\n\n" +
    "📅 *Início:* " + (p.DATA_INICIO || "-") + "\n" +
    "📅 *Término:* " + (p.DATA_FIM || "-") + "\n\n" +
    "💰 *Valor:* R$ " + parseFloat(String(p.VALORPLANEJADO || "0").replace(",", ".")).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + "\n" +
    linhaExec +
    (p.SITUACAO_ATUAL ? "\n\n✅ *Detalhe da Situação:*\n" + p.SITUACAO_ATUAL : "") +
    "\n\n*Deseja mais informações?*\n" +
    "1️⃣ Ver Entregas\n" +
    "2️⃣ Ver Valores\n" +
    "3️⃣ Ver Contratos\n" +
    "4️⃣ Nova Busca"
}];

