}

if (tipo === 'submenu_entregas') {
  contexto.ultimaInteracao = agora;
  staticData.contextos[remetente] = contexto;
  return [{ tipo: 'submenu', submenu: 'entregas', projeto: projetoAtual, busca_limpa: '', remetente, mensagem_retorno: '' }];
}

if (tipo === 'submenu_valores') {
  contexto.ultimaInteracao = agora;
  staticData.contextos[remetente] = contexto;
  return [{ tipo: 'submenu', submenu: 'valores', projeto: projetoAtual, busca_limpa: '', remetente, mensagem_retorno: '' }];
}

if (tipo === 'submenu_contratos') {
  contexto.ultimaInteracao = agora;
  contexto.contratos = null;
  staticData.contextos[remetente] = contexto;
  return [{ tipo: 'submenu', submenu: 'contratos', projeto: projetoAtual, busca_limpa: '', remetente, mensagem_retorno: '' }];
}

if (tipo === 'pergunta_livre') {
  contexto.ultimaInteracao = agora;
  staticData.contextos[remetente] = contexto;
  return [{ tipo: 'pergunta_livre', pergunta: buscaLimpa, projeto_atual: projetoAtual || null, remetente, mensagem_retorno: '', historico_qa: contexto.historico_qa || [] }];
}

if (tipo === 'pular_campo') {
  const campos = { ...camposAcumulados };
  if (!campos.municipio) campos.municipio = 'QUALQUER';
  else if (!campos.situacao) campos.situacao = 'QUALQUER';
  else if (!campos.nome) campos.nome = 'QUALQUER';
  else if (!campos.orgao) campos.orgao = 'QUALQUER';
  else if (!campos.tipo) campos.tipo = 'QUALQUER';
  contexto.campos_acumulados = campos;
  contexto.ultimaInteracao = agora;
  staticData.contextos[remetente] = contexto;
  return [{ tipo: 'busca', busca_limpa: 'refinar', campos_acumulados: campos, campos_faltantes: [], remetente, mensagem_retorno: '' }];
}

// BUSCA (default)
const camposNovos = classificacao.campos || {};
const campos = contexto.projeto_exibido ? {} : { ...camposAcumulados };
Object.keys(camposNovos).forEach(key => {
  if (campos[key] !== 'QUALQUER') campos[key] = camposNovos[key];
});

contexto.campos_acumulados = campos;
contexto.projeto_exibido = false;
contexto.ultimaInteracao = agora;
staticData.contextos[remetente] = contexto;

const campos_faltantes = ['municipio', 'situacao', 'nome', 'orgao', 'tipo'].filter(k => !campos[k]);
const busca_limpa_completa = [campos.nome, campos.municipio, campos.situacao, campos.tipo, campos.orgao]
  .filter(v => v && v !== 'QUALQUER').join(' ') || buscaLimpa;

return [{ tipo: 'busca', busca_limpa: busca_limpa_completa, campos_acumulados: campos, campos_faltantes, remetente, mensagem_retorno: '' }];

const groqResp = $input.item.json;
const remetente = $('ProcessaMensagem').first().json.remetente;

const staticData = $getWorkflowStaticData('global');
if (!staticData.contextos) staticData.contextos = {};
const contexto = staticData.contextos[remetente] || {};
const agora = Date.now();

// Distintos em cache (armazenados pelo PreparaConsulta)
const distintos = staticData.filtrosDistintos || { orgaos: [], tipos: [], municipios: [] };

// Quando é refinamento de seleção, não reprocessar campos via LLM
const buscaOriginal = $('ProcessaMensagem').first().json.busca_limpa;
let resolvido = {};
if (buscaOriginal !== 'refinar') {
  try {
    const texto = groqResp.choices[0].message.content.trim();
    resolvido = JSON.parse(texto.replace(/```json|```/g, '').trim());
  } catch(e) {
    resolvido = {};
  }
}

// Aplicar valores resolvidos ao contexto (substitui vagos por exatos)
const campos = { ...(contexto.campos_acumulados || {}) };
const campos_resolvidos = { ...(contexto.campos_resolvidos || {}) };

function normalizar(s) {
  return (s || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '') // remove diacríticos
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')    // remove pontos, parênteses, etc.
    .replace(/\s+/g, ' ')             // colapsa espaços
    .trim();
}

function encontrarExato(valor, lista) {
  if (!valor || valor === 'null' || valor === null) return null;
  const norm = normalizar(valor);
  if (!norm || norm.length < 2) return null;
  // 1. Match exato normalizado
  const exato = lista.find(v => normalizar(v) === norm);
  if (exato) return exato;
  // 2. Substring: termo do usuário aparece no nome do banco ("educacao" ⊂ "secretaria...educacao")
  const contem = lista.find(v => normalizar(v).includes(norm));
  if (contem) return contem;
  // 3. Multi-palavra: todas as palavras do usuário (≥3 chars) presentes no nome do banco
  const palavras = norm.split(' ').filter(p => p.length >= 3);
  if (palavras.length >= 2) {
    const multiWord = lista.find(v => {
      const vn = normalizar(v);
      return palavras.every(p => vn.includes(p));
    });
    if (multiWord) return multiWord;
  }
  // 4. Inverso: nome do banco contido no termo (fallback para siglas como "celesc")
  const inverso = lista.find(v => norm.includes(normalizar(v)) && normalizar(v).length >= 4);
  return inverso || null;
}

// ORGAO
if (resolvido.orgao && resolvido.orgao !== null) {
  const exato = encontrarExato(resolvido.orgao, distintos.orgaos);
  if (exato) {
    campos.orgao = exato;
    campos_resolvidos.orgao = true;
  } else if (!campos.orgao || campos.orgao === 'QUALQUER') {
    campos.orgao = resolvido.orgao; // mantém o vago como fallback
    campos_resolvidos.orgao = false;
  }
}

// TIPO
if (resolvido.tipo && resolvido.tipo !== null) {
  const exato = encontrarExato(resolvido.tipo, distintos.tipos);
  if (exato) {
    campos.tipo = exato;
    campos_resolvidos.tipo = true;
  } else if (!campos.tipo || campos.tipo === 'QUALQUER') {
    // Tipo vago: descartar se nome cobre a mesma raiz (evita AND over-constrained)
    const tipoRaiz = normalizar(resolvido.tipo).split(' ')[0].substring(0, 4);
    const nomeRaiz = normalizar(resolvido.nome || campos.nome || '').split(' ')[0].substring(0, 4);
    const tipoCobertoPorNome = tipoRaiz.length >= 3 && nomeRaiz.length >= 3 &&
      (tipoRaiz.startsWith(nomeRaiz) || nomeRaiz.startsWith(tipoRaiz));
    if (!tipoCobertoPorNome) {
      campos.tipo = resolvido.tipo;
      campos_resolvidos.tipo = false;
    }
  }
}

// MUNICIPIO (mantém LIKE, só normaliza capitalização)
if (resolvido.municipio && resolvido.municipio !== null) {
  const exato = encontrarExato(resolvido.municipio, distintos.municipios);
  if (exato) {
    campos.municipio = exato;
    campos_resolvidos.municipio = true;
  } else if (!campos.municipio || campos.municipio === 'QUALQUER') {
    campos.municipio = resolvido.municipio;
    campos_resolvidos.municipio = false;
  }
}

// NOME: preservar exatamente como retornado
if (resolvido.nome && resolvido.nome !== null && !campos.nome) {
  campos.nome = resolvido.nome;
}

// ANO: número puro, sem validação de lista
if (resolvido.ano && resolvido.ano !== null) {
  const anoNum = parseInt(resolvido.ano, 10);
  if (anoNum >= 1990 && anoNum <= 2030) {
    campos.ano = String(anoNum);
  }
}

// Gerar filtros_label legível
function abreviarOrgao(orgao) {
  return (orgao || '')
    .replace('Secretaria de Estado da ', 'Sec. de ')
    .replace('Secretaria de Estado de ', 'Sec. de ')
    .replace('Secretaria de Estado do ', 'Sec. do ')
    .replace('Secretaria de Estado dos ', 'Sec. dos ')
    .replace('Fundação Catarinense', 'FC')
    .replace('Departamento Estadual de', 'DE');
}

const partes = [];
if (campos.municipio && campos.municipio !== 'QUALQUER') partes.push('Município: ' + campos.municipio);
if (campos.orgao     && campos.orgao     !== 'QUALQUER') partes.push('Órgão: ' + abreviarOrgao(campos.orgao));
if (campos.situacao  && campos.situacao  !== 'QUALQUER') partes.push('Situação: ' + campos.situacao);
if (campos.tipo      && campos.tipo      !== 'QUALQUER') partes.push('Tipo: ' + campos.tipo);
if (campos.nome      && campos.nome      !== 'QUALQUER') partes.push('Nome: ' + campos.nome);
if (campos.ano) partes.push('Ano: ' + campos.ano);

const filtros_label = partes.length > 0
  ? '\uD83D\uDD0D *Filtros:* ' + partes.join(' | ')
  : '';

// Atualizar contexto
contexto.campos_acumulados = campos;
contexto.campos_resolvidos = campos_resolvidos;
contexto.filtros_label = filtros_label;
contexto.ultimaInteracao = agora;
staticData.contextos[remetente] = contexto;

return [{
  remetente,
  campos,
  campos_resolvidos,
  filtros_label,
  busca_limpa: $('PreparaConsulta').first().json.busca_limpa || '',
  campos_faltantes: []
}];

const input = $input.item.json;
const remetente = input.remetente;
const mensagemRetorno = input.mensagem_retorno;

const pergunta = $('AplicaClassificacao').first().json.pergunta || '';

let respostaLLM = mensagemRetorno;
try {
  respostaLLM = $('RespondePerguntas').first().json.choices[0].message.content.trim();
} catch(e) {}

const staticData = $getWorkflowStaticData('global');
if (!staticData.contextos) staticData.contextos = {};
if (!staticData.contextos[remetente]) staticData.contextos[remetente] = {};
const contexto = staticData.contextos[remetente];
if (!contexto.historico_qa) contexto.historico_qa = [];

contexto.historico_qa.push({ role: 'user', content: pergunta });
contexto.historico_qa.push({ role: 'assistant', content: respostaLLM });

if (contexto.historico_qa.length > 8) {
  contexto.historico_qa = contexto.historico_qa.slice(-8);
}
staticData.contextos[remetente] = contexto;

return [{ remetente, mensagem_retorno: mensagemRetorno }];
